CREATE Proc [dbo].[ReportDateSubCateWiseIssuanceReport] @From as datetime,@To as Datetime,@Login as nvarchar(max) as Declare @ReportName as nvarchar(max);set @ReportName='Branch Issuance Date WISE';select CONVERT(VARCHAR(11),@From,106) as [From],CONVERT(VARCHAR(11),@To,106) as [To],@Login as LoginUser,ism.Date,ism.IssNo,@ReportName as store,Un.Unit as Branch,c.Category,sc.Subcategory,i.Item,U.Unit as PackingType, iu.RecpFactor as UnitQty, b.Branch as 'DSNo', dp.department_name as 'IssNo1', (Select Distinct(Unit) from unit  where UId=issd.Unit) as UnitType,i.itemid, issd.Qty as IssuedQty, issd.Rate as UnitPrice from IssuanceMaster_Store ism  inner join IssuanceDetail_Store issd on ism.IssId=issd.IssId inner join Store s on ism.SId=s.SId inner join Branch b on ism.BRId=b.BRId inner join DepartmentPos dp on dp.BRId = b.BRId left join DemandSheetMaster_Branch db on db.DSId=issd.DSId inner join Item i on issd.ItemId=i.ItemId inner join Subcategory sc on i.SBId = sc.SBId inner join Category c on sc.CId=c.CId inner join ItemUnit iu on i.ItemId=iu.ItemId inner join Unit U on iu.RecpUnit=U.UId inner join Unit Un on iu.PurUnit=Un.UId where ism.Date between @From and @To  and ism.DId=dp.id order by ism.date asc